thm-hyp(
    Type.annotation(@x, X@Topology.ctxt.X),
    Logic.iff(
        Topology.continuous(f@Topology.ctxt.f, x),
        Logic.forall-typed(
            @V,
            Set(B@Topology.ctxt.AB),
            Logic.implies(
                Topology.neighborhood(V, Type.apply(f@Topology.ctxt.f, x)),
                Logic.exists-typed(
                    @U,
                    Set(A@Topology.ctxt.AB),
                    Logic.and(
                        Topology.neighborhood(U, x),
                        Set.subset(
                            Set.sep-typed(@t, A@Topology.ctxt.AB, Set.mem(Type.apply(f@Topology.ctxt.f, t), V)),
                            U
                        )
                    )
                )
            )
        )
    )
)
